import React from 'react';
import {createRoot} from 'react-dom/client';
import {flushSync} from 'react-dom';
import {ThemeProvider} from '@gravity-ui/uikit';
import '@gravity-ui/uikit/styles/styles.css';
import Yagr from '@gravity-ui/yagr';
import {CpuChart} from './CpuChart';
import {demoCpuSource, type CpuSample} from './cpuData';
const tracker = {subscribed:0, unsubscribed:0, disposed:0, observers:0, frames:new Set<number>(), intervals:new Set<number>(), chart:null as Yagr|null, updates:0, durations:[] as number[], receive: (_samples:readonly CpuSample[])=>{}, unmount:()=>{}};
(window as any).tracker = tracker;
const originalDispose = Yagr.prototype.dispose;
Yagr.prototype.dispose = function() {tracker.disposed++; return originalDispose.call(this);};
const originalReflow = Yagr.prototype.reflow;
Yagr.prototype.reflow = function(...args) {tracker.chart = this; return originalReflow.apply(this,args);};
const Observer = window.ResizeObserver;
window.ResizeObserver = class extends Observer {
  constructor(callback:ResizeObserverCallback) {super(callback); tracker.observers++;}
  disconnect() {tracker.observers--; super.disconnect();}
};
const raf = window.requestAnimationFrame;
window.requestAnimationFrame = callback => {
  const id = raf(time => {tracker.frames.delete(id); callback(time);});
  tracker.frames.add(id); return id;
};
const cancel = window.cancelAnimationFrame;
window.cancelAnimationFrame = id => {tracker.frames.delete(id); cancel(id);};
const set = window.setInterval;
window.setInterval = ((...args:Parameters<typeof set>)=>{const id=set(...args); tracker.intervals.add(id);return id;}) as typeof set;
const clear = window.clearInterval;
window.clearInterval = id => {tracker.intervals.delete(id);clear(id);};
const source = {
  getHistory: () => location.search.includes('empty') ? [] : demoCpuSource.getHistory(),
  subscribe(receive:typeof tracker.receive) {tracker.subscribed++;tracker.receive=receive;return ()=>{tracker.unsubscribed++;};},
};
const root = createRoot(document.getElementById('root')"'!);
tracker.unmount = () => flushSync(()=>root.unmount());
root.render(<React.StrictMode><ThemeProvider theme="light"><CpuChart source={source}/></ThemeProvider></React.StrictMode>);
EOF
